sql_query:
SELECT investor_id, investor_name, risk_tolerance
        FROM ATOM_ENTITY_INVESTOR_PROFILE_001
        WHERE risk_tolerance IS NULL OR TRIM(risk_tolerance) = '';

SELECT investor_id, investor_name, time_horizon
        FROM ATOM_ENTITY_INVESTOR_PROFILE_001
        WHERE time_horizon IS NULL OR TRIM(time_horizon) = '';

SELECT investor_id, investor_name, investment_goal
        FROM ATOM_ENTITY_INVESTOR_PROFILE_001
        WHERE investment_goal IS NULL OR TRIM(investment_goal) = '';

SELECT investor_id, investor_name, category
        FROM ATOM_ENTITY_INVESTOR_PROFILE_001
        WHERE category IS NULL OR TRIM(category) = '';

SELECT holding_id, investor_id, investment_name, investment_type
        FROM ATOM_ENTITY_PORTFOLIO_HOLDING_001
        WHERE investment_type IS NULL OR TRIM(investment_type) = '';

SELECT holding_id, investor_id, investment_name, sector
        FROM ATOM_ENTITY_PORTFOLIO_HOLDING_001
        WHERE sector IS NULL OR TRIM(sector) = '';

SELECT holding_id, investor_id, investment_name, segment
        FROM ATOM_ENTITY_PORTFOLIO_HOLDING_001
        WHERE segment IS NULL OR TRIM(segment) = '';

SELECT holding_id, investor_id, investment_name, category
        FROM ATOM_ENTITY_PORTFOLIO_HOLDING_001
        WHERE category IS NULL OR TRIM(category) = '';

SELECT investment_type, COUNT(*) AS holding_count
        FROM ATOM_ENTITY_PORTFOLIO_HOLDING_001
        GROUP BY investment_type;

SELECT risk_tolerance, COUNT(*) AS investor_count
        FROM ATOM_ENTITY_INVESTOR_PROFILE_001
        GROUP BY risk_tolerance;

SELECT time_horizon, COUNT(*) AS investor_count
        FROM ATOM_ENTITY_INVESTOR_PROFILE_001
        GROUP BY time_horizon;

SELECT category, COUNT(*) AS investor_count
        FROM ATOM_ENTITY_INVESTOR_PROFILE_001
        GROUP BY category;

SELECT category, COUNT(*) AS holding_count
        FROM ATOM_ENTITY_PORTFOLIO_HOLDING_001
        GROUP BY category;

SELECT sector, COUNT(*) AS holding_count
        FROM ATOM_ENTITY_PORTFOLIO_HOLDING_001
        GROUP BY sector;

SELECT p.investor_id, p.investor_name
        FROM ATOM_ENTITY_INVESTOR_PROFILE_001 p
        WHERE NOT EXISTS (
            SELECT 1 FROM ATOM_ENTITY_PORTFOLIO_HOLDING_001 o
            WHERE o.investor_id = p.investor_id
        );

SELECT o.holding_id, o.investor_id, o.investment_name
        FROM ATOM_ENTITY_PORTFOLIO_HOLDING_001 o
        WHERE NOT EXISTS (
            SELECT 1 FROM ATOM_ENTITY_INVESTOR_PROFILE_001 p
            WHERE p.investor_id = o.investor_id
        );
